class ROOT(object):
    """ROOT is a sentinel object representing the root target in a glom
    specification. It can be used with :class:`~glom.Let` to capture
    the original input data at any point in a specification.

    .. note::

       This is a singleton and does not need to be constructed.

    >>> from glom import glom, ROOT, Let
    >>> target = {'a': {'b': 1}, 'c': 2}
    >>> glom(target, Let('root', ROOT), 'root')
    {'a': {'b': 1}, 'c': 2}

    """
    __slots__ = ()

    def __repr__(self):
        return 'ROOT'

    def __reduce__(self):
        return (ROOT, ())

    def glomit(self, target, scope):
        return target


# Create ROOT as a singleton instance
ROOT = ROOT()


